#!/usr/bin/env bash
# Arches-Instrumentation — per-repo validation gate (stack: cmake).
# Generated by tools/validate/generate.sh, then adapted to this repo.
#
#   quick   seconds. Format, configure, compile. Run on every change.
#   full    minutes. Adds the whole test suite, coverage and the sanitizers.
#
# WHICH BUILD THIS GATE USES, AND WHY (Task.md A-03)
#
# Host-native, not the aarch64 container. The container is the release and CI
# target -- it proves the code is correct *for the device* -- but on an x86_64
# host it runs under qemu, and the repo's own README notes clang-tidy is "slow
# under qemu". A gate that is slow does not get run on every change, and a gate
# that is not run is not a gate. Host-native configures, builds and runs all
# 321 tests in seconds.
#
# The container build is still required before a release; it is simply not what
# gates an edit. See README "Build".
#
# On the exit contract: this repo's Makefile drives Docker, and Docker being
# absent is exactly the "check could not run" case that must report 77 rather
# than 0. Every check below therefore declares the tools it needs, so an absent
# toolchain is BLOCKED and never a silent pass.
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# The gate builds into its own directory so it never fights a developer's
# build-host-debug/ tree or the container's build-aarch64/.
PRESET_DIR="build-gate"

# --- quick -----------------------------------------------------------------

assert "CMakeLists.txt present" 'test -f CMakeLists.txt'
assert "VERSION present (one version for the whole suite, REQ §2)" 'test -f VERSION'
# The descriptors and catalog are data the daemons load by name; a missing one
# is a runtime failure on a real image, not a build failure, so check here.
assert "alarm catalog present" 'test -f catalog/alarms.yaml'
assert "board descriptors present" 'test -d descriptors'

check "cmake configure parses" "cmake" \
  "cmake -S . -B $PRESET_DIR -DCMAKE_BUILD_TYPE=Debug -DBUILD_TESTING=ON >/dev/null"

# check-format, not `make check-format`: the make target shells into the arm64
# container, which is minutes under qemu for a check that takes under a second
# natively. Same .clang-format, same file set (the cmake target globs lib/,
# daemons/, tools/, test/, catalog/).
check "clang-format clean" "cmake clang-format" \
  "cmake --build $PRESET_DIR --target check-format"

# A compile, not just a configure: a configure-only quick tier passes on code
# that does not build, which is the failure mode quick exists to catch early.
check "compiles" "cmake" "cmake --build $PRESET_DIR -j\"\$(nproc)\""

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

check "tests" "cmake ctest" "ctest --test-dir $PRESET_DIR --output-on-failure"

# The Jenkinsfile makes coverage a hard requirement (REQ §12) rather than a
# report, so the gate does too. COVERAGE_MIN matches the Jenkins default.
#
# gcovr is in the needs list because test/CMakeLists.txt hard-errors at
# configure time when COVERAGE=ON and gcovr is absent -- deliberately, so CI
# cannot report success for a stage that never ran. Without gcovr declared
# here that surfaces as FAIL, which would blame the code for a host that was
# never provisioned. It is a BLOCKED.
check "coverage gate" "cmake ctest gcovr python3" '
  cmake --preset coverage >/dev/null &&
  cmake --build --preset coverage -j"$(nproc)" >/dev/null &&
  ctest --preset coverage --output-on-failure >/dev/null &&
  cmake --build build-coverage --target coverage >/dev/null &&
  python3 tools/ci/coverage_gate.py build-coverage/coverage.xml "${COVERAGE_MIN:-80}"'

# Sanitizers catch what the test suite cannot assert: the fault-injection and
# topology tests exercise concurrent hub/spoke paths, which is where TSan earns
# its runtime.
#
# Both run under `setarch -R` (ASLR disabled). This is not a workaround for a
# code problem -- it is required by the sanitizers themselves on recent
# kernels. ThreadSanitizer maps a fixed shadow-memory region, and when the
# host's vm.mmap_rnd_bits is large enough the main mapping can land inside
# that region; TSan then aborts at startup with
#
#     FATAL: ThreadSanitizer: unexpected memory mapping
#
# Verified on this host (kernel 7.0): the TSan build fails while *generating*
# the alarm header, because alarmgen is itself instrumented and runs at build
# time. The identical binary passes 44/44 under `setarch -R`. The alternative
# is asking every developer to set a sysctl.
SETARCH="setarch $(uname -m) -R"

# The system gRPC/protobuf/abseil are not TSan-instrumented, so TSan reports
# races inside them that it cannot see the synchronisation for. test/tsan.supp
# suppresses those and nothing else -- a race in instr:: code still fails.
export TSAN_OPTIONS="suppressions=$(pwd)/test/tsan.supp${TSAN_OPTIONS:+ $TSAN_OPTIONS}"

check "ASan + UBSan" "cmake ctest setarch" "
  cmake --preset asan >/dev/null &&
  $SETARCH cmake --build --preset asan -j\"\$(nproc)\" >/dev/null &&
  $SETARCH ctest --preset asan --output-on-failure"

check "TSan" "cmake ctest setarch" "
  cmake --preset tsan >/dev/null &&
  $SETARCH cmake --build --preset tsan -j\"\$(nproc)\" >/dev/null &&
  $SETARCH ctest --preset tsan --output-on-failure"

check "clang-tidy" "cmake clang-tidy" \
  "cmake --build $PRESET_DIR --target run-clang-tidy"

report "$TIER"
